/* Transporte publico: listado + CRUD (SITP azul, alimentadores verde, TransMilenio rojo) - responsabilidad única */
const STORAGE_KEY_TRANS = "bc-transporte-v2";
let transMap = null;
let transLayer = null;
let transMarker = null;

function getLocalTrans() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY_TRANS);
    if (raw) {
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed) && parsed.length > 0) return parsed;
    }
  } catch (e) {}
  const seed = (typeof DEFAULT_TRANSPORTE !== "undefined") ? DEFAULT_TRANSPORTE : [];
  localStorage.setItem(STORAGE_KEY_TRANS, JSON.stringify(seed));
  return seed;
}
function setLocalTrans(arr) { localStorage.setItem(STORAGE_KEY_TRANS, JSON.stringify(arr)); }

async function apiTrans(method, path, body) {
  const opts = { method, headers: { "Content-Type": "application/json" } };
  if (body) opts.body = JSON.stringify(body);
  const r = await fetch(path, opts);
  if (!r.ok) throw new Error(await r.text());
  return r.status === 204 ? null : r.json();
}

function colorFor(cat) {
  if (cat === "sitp") return "blue";
  if (cat === "alimentador") return "green";
  if (cat === "transmilenio") return "red";
  return "gray";
}

function renderTransList(items) {
  const ul = document.getElementById("transList");
  if (!ul) return;
  ul.innerHTML = "";
  items.forEach(t => {
    const li = document.createElement("li");
    li.className = "centro-item";
    const color = colorFor(t.categoria);
    let html = `<span style="display:inline-block;width:10px;height:10px;border-radius:50%;background:${color};margin-right:6px;"></span><strong>${t.nombre}</strong><br><small>${t.categoria}</small>`;
    if (t.paradas && t.paradas.length) html += `<br><em>Paradas: ${t.paradas.join(" → ")}</em>`;
    if (t.rutas && t.rutas.length) html += `<br><em>Rutas: ${t.rutas.join(", ")}</em>`;
    li.innerHTML = html;
    const actions = document.createElement("div");
    actions.className = "centro-actions";
    const delBtn = document.createElement("button");
    delBtn.textContent = "Eliminar";
    delBtn.addEventListener("click", async (e) => {
      e.stopPropagation();
      if (!confirm("¿Eliminar " + t.nombre + "?")) return;
      try { await apiTrans("DELETE", "/api/transporte/" + t.id); }
      catch (err) {
        const arr = getLocalTrans().filter(x => x.id !== t.id);
        setLocalTrans(arr);
      }
      await loadTrans();
    });
    actions.appendChild(delBtn);
    li.appendChild(actions);
    ul.appendChild(li);
  });
}

function fillTransForm(t) {
  document.getElementById("transId").value = t ? t.id : "";
  document.getElementById("transNombre").value = t ? t.nombre : "";
  document.getElementById("transCat").value = t ? t.categoria : "sitp";
}

async function loadTrans() {
  try {
    const items = await apiTrans("GET", "/api/transporte");
    setLocalTrans(items);
    renderTransList(items);
    return;
  } catch (e) {
    console.warn("API no disponible, usando datos locales.");
  }
  renderTransList(getLocalTrans());
}

function initTransUI() {
  const form = document.getElementById("transForm");
  if (!form) return;
  form.addEventListener("submit", async (e) => {
    e.preventDefault();
    const id = document.getElementById("transId").value;
    const data = {
      nombre: document.getElementById("transNombre").value,
      categoria: document.getElementById("transCat").value,
      color: colorFor(document.getElementById("transCat").value),
      paradas: [],
      rutas: [],
      estacion: null
    };
    let ok = false;
    try {
      if (id) await apiTrans("PUT", "/api/transporte/" + id, data);
      else await apiTrans("POST", "/api/transporte", data);
      ok = true;
    } catch (err) { /* fallback local */ }
    if (!ok) {
      const arr = getLocalTrans();
      if (id) {
        const i = arr.findIndex(x => x.id === id);
        if (i >= 0) arr[i] = Object.assign({}, arr[i], data);
      } else {
        arr.push(Object.assign({ id: (crypto.randomUUID ? crypto.randomUUID().slice(0,8) : Math.random().toString(36).slice(2,10)) }, data));
      }
      setLocalTrans(arr);
    }
    fillTransForm(null);
    await loadTrans();
  });
  const resetBtn = document.getElementById("transReset");
  if (resetBtn) resetBtn.addEventListener("click", () => fillTransForm(null));
}
